from lib import *
chapter(7,'science','life-processes-in-plants','Life Processes in Plants',
 ('The green kitchen','A plant has no stove, yet it makes its own food. Its leaves are tiny kitchens that use sunlight. We learn how plants make food, take in water and breathe.'),
 [('Photosynthesis',['Photosynthesis is how green plants make food. Leaves take in carbon dioxide from air through tiny pores called stomata, and roots take in water.','Chlorophyll, the green pigment in leaves, captures sunlight. Using the light, the plant turns carbon dioxide and water into glucose and releases oxygen.','The glucose is stored as starch. This is why plants are called producers.']),
  ('Transport in plants',['Roots take water and minerals from the soil. Xylem tubes carry water upward to the leaves. Phloem tubes carry food from leaves to other parts.']),
  ('Transpiration',['Transpiration is the loss of water as vapour from the leaves through stomata. It cools the plant and pulls water up from the roots.']),
  ('Respiration and nutrition',['Plants also respire: they take in oxygen and release carbon dioxide, day and night.','Some plants, like insect-eating pitcher plants, get extra nutrients from insects.'])],
 [('What does a plant need to make food?',[('Sunlight, carbon dioxide, water and chlorophyll.','The four needs.'),('It gives out oxygen.','The by-product.')])],
 ('Explain why plants are important for animals.',['They make food and oxygen.'],['Thinking plants breathe only at night.']),
 ['Photosynthesis makes food using sunlight.','Xylem carries water; phloem carries food.','Transpiration loses water vapour.','Plants also respire.'],
 [mcq('1',1,'Plants make food by','photosynthesis',[('digestion','Animals digest food.'),('respiration','That releases energy.')],'Using sunlight.'),
  mcq('2',1,'Chlorophyll is','a green pigment',[('a gas','It is a pigment.'),('a root','It is in leaves.')],'It traps light.'),
  tf('3',1,'Plants give out oxygen in photosynthesis.',True,'It is a by-product.'),
  mcq('4',1,'Water goes up a plant through','xylem',[('phloem','Phloem carries food.'),('stomata','Stomata are pores.')],'Up from roots.'),
  mcq('5',2,'Loss of water vapour from leaves is','transpiration',[('germination','Sprouting of seeds.'),('digestion','Not in plants.')],'Through stomata.'),
  mcq('6',2,'Food is carried by','phloem',[('xylem','Xylem carries water.'),('roots','Roots absorb water.')],'From leaves to other parts.'),
  tf('7',2,'Plants respire only at night.',False,'They respire all the time.'),
  mcq('8',3,'The gas taken in during photosynthesis is','carbon dioxide',[('oxygen','It is given out.'),('nitrogen','Plants do not use it directly.')],'Through stomata.')],
 keep=['photosynthesis','chlorophyll','stomata'])
chapter(7,'science','light-shadows-and-reflections','Light, Shadows and Reflections',
 ('Shadow play','On a sunny day your shadow follows you. In the evening it grows long. Light and shadows are linked, and mirrors can send light back.'),
 [('Sources of light',['Luminous objects make their own light, such as the Sun, a torch and a candle. Non-luminous objects like the Moon only reflect light.']),
  ('Light and materials',['Transparent materials let light pass fully. Translucent ones let some pass. Opaque ones block light.','Light travels in straight lines.']),
  ('Shadows',['A shadow forms when an opaque object blocks light. It is dark and has the same shape as the object.','A shadow gets bigger when the object is close to the light and smaller when the object is far.','A pinhole camera uses a tiny hole to make an upside-down image on a screen because light moves in straight lines.']),
  ('Reflection',['Reflection is light bouncing off a surface. The angle of incidence equals the angle of reflection.','A plane mirror forms an image of the same size, as far behind the mirror as the object is in front, and left and right are swapped.'])],
 [('A girl stands 1 m in front of a mirror. How far is her image from her?',[('The image is as far behind the mirror.','Equal distance.'),('1 m behind the mirror, so 2 m from her.','Add both.')])],
 ('Explain why a shadow forms.',['An opaque object blocks the straight path of light.'],['Thinking light bends round objects.']),
 ['Light travels in straight lines.','Opaque objects make shadows.','Angle of incidence equals angle of reflection.','Plane mirror image is same size and laterally inverted.'],
 [mcq('1',1,'Which is luminous?','The Sun',[('The Moon','It reflects sunlight.'),('A mirror','It reflects light.')],'It makes its own light.'),
  mcq('2',1,'Light travels in','straight lines',[('curves','It only seems to when reflected or refracted.'),('circles','Not circles.')],'This is why shadows have sharp shapes.'),
  tf('3',1,'An opaque object makes a shadow.',True,'It blocks light.'),
  mcq('4',1,'In a plane mirror the image is','the same size as the object',[('larger','A plane mirror does not magnify.'),('smaller','Not reduced.')],'Equal in size.'),
  mcq('5',2,'Angle of incidence equals','angle of reflection',[('angle of the mirror','Not related.'),('zero','Only when light hits straight on.')],'The law of reflection.'),
  mcq('6',2,'A pinhole camera makes an image that is','upside down',[('upright','It is inverted.'),('missing','It does produce an image.')],'Straight-line travel of light.'),
  tf('7',2,'The Moon makes its own light.',False,'It reflects sunlight.'),
  mcq('8',3,'A shadow is biggest when the object is','close to the light',[('far from the light','The shadow is smaller.'),('behind the screen','No shadow.')],'More light is blocked.')],
 keep=['reflection','shadow','opaque'])
chapter(7,'science','earth-moon-and-the-sun','Earth, Moon and the Sun',
 ('Day, night and months','The Sun rises and sets each day. The Moon changes shape through the month. The year brings summer and winter. All come from how Earth, Moon and Sun move.'),
 [('Rotation and revolution',['Earth spins on its axis once in 24 hours. This is rotation and it causes day and night.','Earth also goes around the Sun once in about 365 and a quarter days. This is revolution.','Earth\'s axis is tilted. Because of the tilt and the revolution we get seasons.']),
  ('Seasons',['When the northern part of Earth is tilted towards the Sun it gets more direct light for longer and has summer. When it is tilted away it has winter.']),
  ('Phases of the Moon',['The Moon shines by reflecting sunlight. As it goes round Earth in about a month we see different parts of its lit side, called phases.','From new moon, when it is not seen, the lit part grows to full moon and then shrinks again.']),
  ('Eclipses',['A solar eclipse occurs when the Moon comes between the Sun and Earth and blocks the Sun\'s light. A lunar eclipse occurs when Earth comes between the Sun and Moon and its shadow falls on the Moon.','Never look at the Sun during a solar eclipse without proper eye protection.'])],
 [('What causes day and night?',[('Earth rotates once in 24 hours.','Rotation.'),('The side facing the Sun has day; the other has night.','Result.')])],
 ('Explain why we have seasons.',['Earth\'s tilt and revolution.'],['Thinking seasons come from distance to the Sun.']),
 ['Rotation causes day and night.','Revolution and tilt cause seasons.','The Moon shows phases.','Eclipses occur when Sun, Moon and Earth line up.'],
 [mcq('1',1,'Day and night are caused by Earth\'s','rotation',[('revolution','This gives years and seasons.'),('tilt only','Tilt gives seasons.')],'Spinning once a day.'),
  mcq('2',1,'Earth revolves around the Sun in about','365 days',[('24 hours','That is rotation.'),('30 days','That is the Moon\'s cycle.')],'A year.'),
  tf('3',1,'The Moon has its own light.',False,'It reflects sunlight.'),
  mcq('4',1,'A solar eclipse is when the','Moon is between Sun and Earth',[('Earth is between Sun and Moon','That is a lunar eclipse.'),('Sun is behind Earth only','Not a definition.')],'The Moon blocks the Sun.'),
  mcq('5',2,'Seasons are caused by','Earth\'s tilt and revolution',[('distance from the Sun','The distance changes little.'),('the Moon','The Moon causes phases.')],'Tilted axis.'),
  mcq('6',2,'The Moon takes about this long to go round Earth','one month',[('one day','That is Earth\'s rotation.'),('one year','That is Earth round the Sun.')],'About 27 to 29 days.'),
  tf('7',2,'It is safe to look at a solar eclipse without protection.',False,'It can damage the eyes.'),
  mcq('8',3,'Phases occur because we see','different amounts of the Moon\'s lit side',[('Earth\'s shadow every night','That happens only in a lunar eclipse.'),('the Moon changing size','Its size does not change.')],'Sunlight lights half the Moon.')],
 keep=['rotation','revolution','eclipse'])
